def subtract(a, b):
    def merge_intervals(intervals):
        """Merge overlapping/touching intervals and remove empty ones."""
        if not intervals:
            return []

        # Filter out empty intervals and sort
        valid = [iv for iv in intervals if iv[0] < iv[1]]
        if not valid:
            return []

        valid.sort()
        merged = [valid[0]]

        for start, end in valid[1:]:
            last_start, last_end = merged[-1]
            if start <= last_end:
                # Overlapping or touching, merge
                merged[-1] = [last_start, max(last_end, end)]
            else:
                # Disjoint, add new interval
                merged.append([start, end])

        return merged

    # Merge intervals in both a and b
    a_merged = merge_intervals(a)
    b_merged = merge_intervals(b)

    if not a_merged:
        return []

    if not b_merged:
        return a_merged

    result = []

    for a_start, a_end in a_merged:
        current_ranges = [[a_start, a_end]]

        for b_start, b_end in b_merged:
            new_ranges = []

            for curr_start, curr_end in current_ranges:
                # No overlap
                if curr_end <= b_start or curr_start >= b_end:
                    new_ranges.append([curr_start, curr_end])
                else:
                    # There is overlap, keep the parts before and after
                    if curr_start < b_start:
                        new_ranges.append([curr_start, b_start])
                    if curr_end > b_end:
                        new_ranges.append([b_end, curr_end])

            current_ranges = new_ranges

        result.extend(current_ranges)

    return result

